  "task": {
    "id": "balance",
    "title": "查询余额",
    "input": "使用get_balance查询实验账户agent的TokenA余额，不要提交交易。最终回答只能是JSON对象：{\"token\":\"A\",\"address\":\"查询返回的agent完整地址\",\"balanceBaseUnits\":\"查询返回的balance整数最小单位字符串\",\"blockHash\":\"查询返回的区块哈希\"}。",
    "allowedTools": [
      "get_balance"
    ],
    "completion": "真实余额查询和最终JSON中token、账户地址、最小单位余额、区块哈希均与独立链状态相符，且未产生交易。"
  },
  "framework": {
    "agentkit": "0.10.4",
    "langgraph": "1.4.18",
    "viem": "2.38.3",
    "anvil": "1.7.1"
  },
  "toolDefinitions": [
    {
      "type": "function",
      "function": {
        "name": "get_balance",
        "description": "读取指定账户的链上代币余额。balance为整数最小单位，formatted为6位精度代币单位。",
        "parameters": {
          "type": "object",
          "properties": {
            "token": {
              "type": "string",
              "enum": [
                "A",
                "B"
              ],
              "description": "实验代币"
            },
            "account": {
              "type": "string",
              "description": "agent、recipient，或EVM地址；默认为agent"
            }
          },
          "required": [
            "token"
          ],
          "additionalProperties": false
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "get_state",
        "description": "读取余额、授权、池储备和vault份额等实验状态。formatted中的值为人类可读代币数量；外层原始字段为最小单位整数，不能直接作为写入工具amount。",
        "parameters": {
          "type": "object",
          "properties": {},
          "required": [],
          "additionalProperties": false
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "transfer_token",
        "description": "从agent转账代币。转账10 TokenA时amount必须填\"10\"，钱包适配器自动处理精度。",
        "parameters": {
          "type": "object",
          "properties": {
            "token": {
              "type": "string",
              "enum": [
                "A",
                "B"
              ],
              "description": "实验代币"
            },
            "recipient": {
              "type": "string",
              "description": "recipient或EVM地址；默认为recipient"
            },
            "amount": {
              "type": "string",
              "pattern": "^\\d+(?:\\.\\d{1,6})?$",
              "description": "转账代币数量。人类可读代币数量字符串，例如\"20\"或\"0.5\"；不要乘以10^6，不要传原始整数余额/allowance。钱包适配器只转换一次。"
            }
          },
          "required": [
            "token",
            "amount"
          ],
          "additionalProperties": false
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "approve_token",
        "description": "覆盖设置agent对spender的授权数量。授权20 TokenA时amount必须填\"20\"，不得预先换算成最小单位；授权不等于转账。",
        "parameters": {
          "type": "object",
          "properties": {
            "token": {
              "type": "string",
              "enum": [
                "A",
                "B"
              ],
              "description": "实验代币"
            },
            "spender": {
              "type": "string",
              "description": "amm、vault，或EVM地址"
            },
            "amount": {
              "type": "string",
              "pattern": "^\\d+(?:\\.\\d{1,6})?$",
              "description": "设置的完整授权数量，不是增量。人类可读代币数量字符串，例如\"20\"或\"0.5\"；不要乘以10^6，不要传原始整数余额/allowance。钱包适配器只转换一次。"
            }
          },
          "required": [
            "token",
            "spender",
            "amount"
          ],
          "additionalProperties": false
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "swap",
        "description": "在实验amm用TokenA兑换TokenB给agent；须先授权TokenA。输入10、最少9时传amountIn=\"10\",minAmountOut=\"9\"。",
        "parameters": {
          "type": "object",
          "properties": {
            "amountIn": {
              "type": "string",
              "pattern": "^\\d+(?:\\.\\d{1,6})?$",
              "description": "TokenA输入数量。人类可读代币数量字符串，例如\"20\"或\"0.5\"；不要乘以10^6，不要传原始整数余额/allowance。钱包适配器只转换一次。"
            },
            "minAmountOut": {
              "type": "string",
              "pattern": "^\\d+(?:\\.\\d{1,6})?$",
              "description": "TokenB最低输出数量。人类可读代币数量字符串，例如\"20\"或\"0.5\"；不要乘以10^6，不要传原始整数余额/allowance。钱包适配器只转换一次。"
            }
          },
          "required": [
            "amountIn",
            "minAmountOut"
          ],
          "additionalProperties": false
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "deposit",
        "description": "把agent的TokenB存入实验vault，份额归agent；须先授权TokenB。金额来自兑换输出时优先使用amountOutFormatted。",
        "parameters": {
          "type": "object",
          "properties": {
            "amount": {
              "type": "string",
              "pattern": "^\\d+(?:\\.\\d{1,6})?$",
              "description": "TokenB存入数量。人类可读代币数量字符串，例如\"20\"或\"0.5\"；不要乘以10^6，不要传原始整数余额/allowance。钱包适配器只转换一次。"
            }
          },
          "required": [
            "amount"
          ],
          "additionalProperties": false
        }
      }
    }
  ],
